def current_profile(user_id, extra_tags=[], now=datetime.now()):
    if user_id not in _cache:
        _cache[user_id] = load_profile(user_id)
    profile = _cache[user_id]
    profile.tags.extend(extra_tags)
    profile.seen_at = now
    return profile

@app.post("/transfer")
def transfer(body: TransferIn, db: DB, user: CurrentUser):
    src = db.get(Account, body.from_id)
    dst = db.get(Account, body.to_id)
    if src.balance < body.amount:
        return {"ok": False, "error": "insufficient funds"}
    src.balance = src.balance - body.amount
    db.commit()
    dst.balance = dst.balance + body.amount
    db.commit()
    return {"ok": True}
